def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider, preferring a color that appears only on that line.
    divider = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            color = row[0]
            if sum(cell == color for rr, line in enumerate(grid) if rr != r for cell in line) == 0:
                divider = ("row", r)
                break
    if divider is None:
        for c in range(w):
            color = grid[0][c]
            if all(grid[r][c] == color for r in range(h)):
                if sum(grid[r][cc] == color for r in range(h) for cc in range(w) if cc != c) == 0:
                    divider = ("col", c)
                    break

    if divider[0] == "row":
        i = divider[1]
        a, b = grid[:i], grid[i + 1:]
        common = set(v for row in a for v in row) & set(v for row in b for v in row)
        fill = min(common, key=lambda x: sum(v == x for row in a + b for v in row))
        return [[3 if a[r][c] == b[r][c] else fill for c in range(w)]
                for r in range(min(len(a), len(b)))]
    else:
        i = divider[1]
        a = [row[:i] for row in grid]
        b = [row[i + 1:] for row in grid]
        common = set(v for row in a for v in row) & set(v for row in b for v in row)
        fill = min(common, key=lambda x: sum(v == x for row in a + b for v in row))
        return [[3 if a[r][c] == b[r][c] else fill for c in range(min(len(a[0]), len(b[0])))]
                for r in range(h)]
